-- 526: Original BrillaPrep NSMQ subj_nsmq_chemistry true_false_problem_of_day beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_526_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_526_guard;
INSERT INTO _migration_526_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_pod_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_chem_stoichiometry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the mass of calcium carbonate that must decompose completely to produce 4.4 g of carbon dioxide. (CaCO₃ → CaO + CO₂; Ca = 40, C = 12, O = 16)' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '10 g' AND q.explanation IS 'M(CO₂) = 12 + 2(16) = 44 g/mol, so n(CO₂) = 4.4/44 = 0.10 mol. The balanced equation shows a 1:1 mole ratio, so n(CaCO₃) = 0.10 mol. M(CaCO₃) = 40 + 12 + 3(16) = 100 g/mol, giving mass = 0.10 × 100 = 10 g.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_pod_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_526_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_pod_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_chem_equilibrium' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A 0.100 M solution of the weak monoprotic acid HA has [H⁺] = 1.0 × 10⁻³ M at equilibrium. Calculate the acid dissociation constant Ka.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS 'Ka ≈ 1.0 × 10⁻⁵ mol dm⁻³' AND q.explanation IS 'For HA ⇌ H⁺ + A⁻, the dissociation gives [H⁺] = [A⁻] = 1.0 × 10⁻³ M and [HA] = 0.100 − 0.001 = 0.099 M. Then Ka = [H⁺][A⁻]/[HA] = (1.0 × 10⁻³)²/0.099 ≈ 1.01 × 10⁻⁵ ≈ 1.0 × 10⁻⁵ mol dm⁻³.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_pod_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_526_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_tf_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_chem_atomic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The mass number of an atom is the sum of its protons and neutrons.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'Mass number A counts the nucleons: A = Z + N, where Z is the proton (atomic) number and N the neutron count. Electrons are excluded because their mass is negligible compared with a proton or neutron.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_tf_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_526_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_tf_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_chem_bonding' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A covalent bond involves the complete transfer of electrons from one atom to another.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'False' AND q.explanation IS 'Covalent bonding is the sharing of electron pairs between atoms, as in H₂ or CH₄. Complete transfer of electrons produces ions and is the defining feature of ionic bonding, as in sodium chloride.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_tf_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_526_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_tf_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_chem_organic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Ethene rapidly decolourises bromine water at room temperature.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'Ethene is unsaturated: its C=C double bond undergoes an addition reaction with bromine to form colourless 1,2-dibromoethane, so the orange bromine colour disappears. This is the standard test for unsaturation.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_tf_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_526_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_tf_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_chem_stoichiometry' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'One mole of any gas occupies a volume of 22.4 dm³ at standard temperature and pressure.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'At s.t.p. (0 °C and 1 atmosphere) the molar volume of an ideal gas is 22.4 dm³/mol, so one mole of any gas occupies 22.4 dm³. This Avogadro-law result is used constantly in reacting-gas calculations.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_tf_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_chem_pod_b002_001', 'topic_nsmq_chem_stoichiometry', 'subj_nsmq_chemistry', 'exam_nsmq', NULL, NULL, 'Calculate the mass of calcium carbonate that must decompose completely to produce 4.4 g of carbon dioxide. (CaCO₃ → CaO + CO₂; Ca = 40, C = 12, O = 16)', 'problem', 'problem_of_day', NULL, '10 g', 'M(CO₂) = 12 + 2(16) = 44 g/mol, so n(CO₂) = 4.4/44 = 0.10 mol. The balanced equation shows a 1:1 mole ratio, so n(CaCO₃) = 0.10 mol. M(CaCO₃) = 40 + 12 + 3(16) = 100 g/mol, giving mass = 0.10 × 100 = 10 g.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
